static class LRUCache {
    Map<Integer, Node> map;
    Node head;
    Node tail;
    int capacity;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        map = new HashMap<>();
        head = new Node();
        tail = new Node();
        head.next = tail;
        tail.pre = head;
    }

    public int get(int key) {
        if (!map.containsKey(key)) {
            return -1;
        }
        Node node = map.get(key);
        unLinkNode(node);
        move2Head(node);
        return node.val;
    }

    public void put(int key, int value) {
        Node node;
        if (map.containsKey(key)) {
            node = map.get(key);
            node.val = value;
            unLinkNode(node);
        } else {
            node = new Node(key, value);
            map.put(key, node);
        }
        move2Head(node);
        if (map.size() > capacity) {
            Node last = tail.pre;
            unLinkNode(last);
            map.remove(last.key);
        }
    }

    private void unLinkNode(Node node) {
        node.pre.next = node.next;
        node.next.pre = node.pre;
    }

    private void move2Head(Node node) {
        node.next = head.next;
        node.pre = head;
        head.next.pre = node;
        head.next = node;
    }

    static class Node {
        Node next;
        Node pre;
        int val;
        int key;

        Node() {}

        Node(int key, int val) {
            this.key = key;
            this.val = val;
        }
    }
}

